const S={page:'home',alt:1},$=s=>document.querySelector(s),C=$('#content');
const T=m=>{const t=$('#toast');t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)};
const H=(k,t,d,a='')=>`<div class="page-head"><div><div class="eyebrow">${k}</div><h1>${t}</h1><p>${d}</p></div><div>${a}</div></div>`;
const V=()=>`<div class="card"><div class="row-between"><strong>Validation gate</strong><span class="chip warn">2 review</span></div>${[['ok','Geometry integrity','No overlaps or broken room boundaries.','PASS'],['warn','Service circulation','980 mm observed · 1000 mm required.','MS-RST-014'],['ok','Material suitability','Selected finish is approved.','MAT-023'],['warn','MEP coordination','2 outlets require relocation.','MEP-CHK']].map(x=>`<div class="validation-item"><i class="status-dot ${x[0]}"></i><div><strong>${x[1]}</strong><small>${x[2]}</small></div><code>${x[3]}</code></div>`).join('')}<button class="btn accent" style="width:100%;margin-top:10px" onclick="nav('validation')">Review checklist</button></div>`;
const metric=(a,b,c)=>`<div class="card metric"><small>${a}</small><strong>${b}</strong><span>${c}</span></div>`;
function home(){return H('ARCHITECTURAL INTELLIGENCE','Good evening, Adwin.','Four active projects, two decisions waiting for review, and one timeline risk.',`<button class="btn primary" onclick="nav('genesis')">New project</button>`)+`<div class="grid cols-4">${metric('Active projects','04','Across 3 stages')}${metric('Pending approvals','02','1 design · 1 technical')}${metric('Validation health','94%','+3% this week')}${metric('Schedule at risk','01','Preview due Friday')}</div><div class="section-title">Active projects</div><div class="grid cols-3">${['Casa Nusa Restaurant','Kura Beach Club','Atria Boutique Hotel'].map((n,i)=>`<div class="card project-card"><div class="project-preview"></div><div class="project-body"><div class="row-between"><strong>${n}</strong><span class="chip ${i===1?'warn':'ok'}">${['DD','Concept','Technical'][i]}</span></div><p class="mini-stat">${i?'Hospitality · Bali':'Restaurant · Jakarta'}</p><div class="progress"><i style="width:${[72,48,86][i]}%"></i></div></div></div>`).join('')}</div><div class="section-title">ARCHON brief</div><div class="grid cols-2"><div class="card"><strong>Design intelligence</strong><p class="mini-stat">Layout A scores highest for service circulation and kitchen adjacency. Moving VIP entry 400 mm south can recover 2 seats.</p><button class="btn" onclick="nav('layout')">Open layout study</button></div><div class="card"><strong>Operational signal</strong><p class="mini-stat">Furniture details are the critical path for Friday's technical preview.</p><button class="btn" onclick="nav('timeline')">Review timeline</button></div></div>`}
function genesis(){return `<div class="genesis">${H('PROJECT GENESIS','Start from intent, not from files.','Voice or text becomes a structured, reviewable project baseline.')}<div class="card brief-box"><div class="row-between"><strong>Talk to ARCHON</strong><span class="chip">VOICE READY</span></div><textarea>Restaurant in PIK2, site 18 x 32 m, two levels, FTF 4 m. Kitchen 28%, 2 VIP rooms, visible bar. Main entrance 3 m high, windows 2.4 m high with 600 mm sill, service corridor minimum 1.2 m.</textarea><div class="row-between"><span class="mini-stat">Detected: site · levels · program · openings · circulation</span><button class="btn accent" onclick="T('Structured brief generated for review.')">Interpret brief ✦</button></div></div><div class="section-title">Structured brief</div><div class="card"><div class="form-grid">${[['Project name','PIK2 Restaurant Concept'],['Building type','Restaurant'],['Site width','18,000 mm'],['Site depth','32,000 mm'],['Levels','2'],['Floor-to-floor','4,000 mm'],['Main entrance','3,000 mm'],['Window sill','600 mm']].map(x=>`<div class="field"><label>${x[0]}</label><input value="${x[1]}"></div>`).join('')}</div><div class="section-title">Initial rules</div><div class="lock-row"><span class="lock-chip editable">Service corridor ≥1200</span><span class="lock-chip editable">Kitchen target 28%</span><span class="lock-chip editable">Door H 3000</span><span class="lock-chip editable">Sill 600</span></div><div style="text-align:right;margin-top:16px"><button class="btn primary" onclick="T('Proposed ChangeSet CHG-001 created.')">Create baseline proposal</button></div></div></div>`}
function dashboard(){return H('CASA NUSA RESTAURANT','Project dashboard','Design state, technical health, approvals, schedule and synchronization in one view.')+`<div class="grid cols-4">${metric('Design stage','DD','Design Development')}${metric('Approved version','V14','18 Sep baseline')}${metric('Drawing set','68%','34 of 50 sheets')}${metric('Estimated cost','3.84B','IDR · +1.7%')}</div><div class="grid cols-2" style="margin-top:14px"><div class="card"><strong>Design maturity</strong><div class="progress"><i style="width:76%"></i></div><div class="section-title">Current decisions</div>${['Kitchen wall +300 mm','Facade ACP palette','Banquette detail'].map((x,i)=>`<div class="validation-item"><i class="status-dot ${i===1?'ok':'warn'}"></i><div><strong>${x}</strong><small>${i===1?'Approved V14':'Waiting for review'}</small></div></div>`).join('')}</div><div>${V()}<div class="card" style="margin-top:14px"><strong>Next milestone</strong><p>Technical preview · Friday 16:00</p><div class="risk-banner">Furniture detail completion is the critical path.</div></div></div></div>`}
function layout(){return H('DESIGN EXPLORATION','Layout studio','Compare alternatives by operational, spatial and rule-based performance.',`<button class="btn accent" onclick="T('Generating three alternatives…')">Generate alternatives ✦</button>`)+`<div class="workspace"><div class="card workspace-main"><div class="toolbar">${['Select','Markup','Measure','Adjacency','Circulation','Grid'].map(x=>`<span class="tool">${x}</span>`).join('')}</div><div class="grid cols-3">${[1,2,3].map((n,i)=>`<div class="alternative ${S.alt===n?'selected':''}" onclick="S.alt=${n};R()"><span class="score">${[92,86,81][i]} score</span><div class="alt-plan"><i class="blk" style="left:12%;top:12%;width:42%;height:31%"></i><i class="blk" style="right:10%;top:14%;width:29%;height:47%"></i><i class="blk" style="left:15%;bottom:11%;width:33%;height:36%"></i><i class="blk" style="left:51%;bottom:12%;width:38%;height:25%"></i></div><p><strong>Layout ${String.fromCharCode(65+i)}</strong><br><span class="mini-stat">${['Best service flow','Best seating yield','Best VIP privacy'][i]}</span></p></div>`).join('')}</div><div class="callout"><b>ARCHON rationale</b><br>Layout A shortens kitchen-to-service path 18% and gives strongest bar visibility.</div></div><div class="workspace-side"><div class="card"><strong>Selected · Layout ${String.fromCharCode(64+S.alt)}</strong><div class="param-list">${[['Dining seats',[0,142,148,136][S.alt]],['Kitchen','126 m²'],['Service aisle','1,200 mm'],['VIP rooms','2']].map(x=>`<div class="param"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div><button class="btn primary" style="width:100%" onclick="T('Promotion proposal created. Validation required.')">Promote to Building Model</button></div>${V()}</div></div>`}
function canvas(){return H('NON-AUTHORITATIVE EXPLORATION','Design canvas','Ideas stay free until they are deliberately promoted into technical truth.')+`<div class="workspace"><div class="card workspace-main"><div class="toolbar"><span class="tool">Move</span><span class="tool">Connect</span><span class="tool">Comment</span><span class="tool">AI Generate</span><span class="chip warn" style="margin-left:auto">NON-AUTHORITATIVE</span></div><div class="canvas-board">${[['45','55','Approved Brief · V14','Restaurant, 2 levels'],['280','40','Layout A','Promoted candidate · 92'],['520','80','Facade study','Stone + bronze'],['750','55','Night render','3000K uplight'],['510','265','Bar concept','Organic island'],['750','285','Material v03','Dark timber + stone']].map(x=>`<div class="node" style="left:${x[0]}px;top:${x[1]}px"><h4>${x[2]}</h4><p>${x[3]}</p></div>`).join('')}</div></div><div class="workspace-side"><div class="card"><strong>Design locks</strong><div class="lock-row" style="margin-top:10px"><span class="lock-chip locked">🔒 Structure</span><span class="lock-chip locked">🔒 Layout</span><span class="lock-chip editable">Materials</span><span class="lock-chip editable">Lighting</span><span class="lock-chip locked">🔒 Camera</span></div></div><div class="card"><strong>Generation intent</strong><p class="mini-stat">Make the facade warmer and more premium. Keep openings and geometry unchanged.</p><button class="btn accent" style="width:100%" onclick="T('Visual task queued with geometry locks.')">Generate alternatives ✦</button></div></div></div>`}
function studio3d(){return H('AUTHORING VIEW','3D studio','Selection, direct manipulation, text and voice share one governed change pipeline.')+`<div class="workspace"><div class="card workspace-main"><div class="toolbar">${['Orbit','Pan','Select','Section','Measure','Materials','Lighting'].map(x=>`<span class="tool">${x}</span>`).join('')}<span class="chip" style="margin-left:auto">MOCK 3D VIEW</span></div><div class="model3d"><div class="cube"></div><div class="light-cone" style="left:40%;top:45%"></div><div class="light-cone" style="left:52%;top:43%"></div></div></div><div class="workspace-side"><div class="card"><div class="row-between"><strong>Selected object</strong><span class="chip">WALL-018</span></div><div class="param-list">${[['Length','6,420 mm'],['Height','4,000 mm'],['Material','ACP-YEL-03'],['Authority','ARCHON']].map(x=>`<div class="param"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div></div>${V()}</div></div>`}
function building(){return H('AUTHORITATIVE TRUTH','Building model','Semantic objects, dimensions, relationships and constraints drive every downstream representation.')+`<div class="workspace"><div class="card workspace-main"><div class="tabs"><button class="tab active">Objects</button><button class="tab">Relationships</button><button class="tab">Constraints</button><button class="tab">Dependencies</button></div><div class="grid cols-2"><div>${['LEVEL 01','Dining · 18 objects','Kitchen · 13 objects','VIP 01 · 8 objects','Facade · 21 objects'].map((x,i)=>`<div class="sheet-item ${i===2?'active':''}">${x}</div>`).join('')}</div><div><strong>Kitchen · ROOM-012</strong><div class="param-list">${[['ARCHON ID','room_01JX…12'],['Area','126.4 m²'],['Clear height','3,400 mm'],['Level','L01'],['Rule set','RST-KITCHEN-v3']].map(x=>`<div class="param"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div><div class="callout">7 walls · 2 doors · 14 MEP points · 3 sheets · 18 BOQ lines depend on this room.</div></div></div></div><div class="workspace-side">${V()}<div class="card"><strong>Change governance</strong><p class="mini-stat">CHG-1948 · Kitchen wall +300 mm east · waiting for review.</p><button class="btn primary" style="width:100%" onclick="nav('validation')">Review before approval</button></div></div></div>`}
function technical(){return H('DOCUMENTATION','Technical drawings','Plans, elevations, sections, furniture details and MEP sheets derived from the approved model.',`<button class="btn accent" onclick="T('7 affected sheets identified.')">Regenerate affected sheets</button>`)+`<div class="sheet-grid"><div class="card"><strong>Drawing set</strong><div class="sheet-list" style="margin-top:10px">${['A-101 Ground Floor','A-201 North Elevation','A-301 Section A-A','ID-401 Kitchen','ID-601 Bar Detail','M-101 HVAC','E-101 Lighting'].map((x,i)=>`<div class="sheet-item ${i===1?'active':''}">${x}<small style="display:block;color:${i===4?'var(--warn)':'#667386'}">${i===4?'OUTDATED':'V14 current'}</small></div>`).join('')}</div></div><div class="drawing"><b>CASA NUSA RESTAURANT</b><div class="building-elev"><div class="window" style="left:8%;top:28%;width:18%;height:42%"></div><div class="window" style="left:31%;top:28%;width:18%;height:42%"></div><div class="window" style="left:54%;top:28%;width:18%;height:42%"></div><div class="window" style="left:77%;top:28%;width:15%;height:42%"></div></div></div></div>`}
function materials(){return H('MATERIAL INTELLIGENCE','Materials','One governed library for appearance, specification, supplier data and engine mappings.')+`<div class="material-grid">${[['#b9b1a2','Limestone','STONE-07'],['#b4895a','Oak Natural','WOOD-04'],['#3b3f45','ACP Graphite','ACP-08'],['#b08f67','Bronze','METAL-06'],['#b7b2aa','Terrazzo','FLOOR-11']].map(x=>`<div class="material-card"><div class="swatch" style="background:${x[0]}"></div><div class="mat-body"><strong>${x[1]}</strong><small>${x[2]} · Approved</small><p><span class="chip ok">Mapped</span></p></div></div>`).join('')}</div>`}
function boq(){return H('COST INTELLIGENCE','BOQ & cost','Quantities and cost impacts stay linked to approved design state.')+`<div class="grid cols-4">${metric('Current estimate','3.84B','IDR')}${metric('Change vs V13','+65M','+1.7%')}${metric('Mapped quantities','91%','287 items')}${metric('Price freshness','84%','16 need update')}</div><div class="card" style="margin-top:14px"><table class="boq-table"><thead><tr><th>Item</th><th>Qty</th><th>Source</th><th>Total</th></tr></thead><tbody>${[['Honed limestone','186 m²','Vendor quote','232,500,000'],['Custom banquette','21.6 lm','MS precedent','146,880,000'],['ACP facade','94 m²','Supplier list','103,400,000'],['Lighting package','1 lot','Consultant draft','285,000,000']].map(x=>`<tr>${x.map(y=>`<td>${y}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function validation(){return H('GOVERNANCE','Validation center','Every authoritative change explains checks, evidence, sources and approval responsibility.',`<button class="btn accent" onclick="T('Validation rerun complete: 8 pass · 2 warning.')">Run checks again</button>`)+`<div class="grid cols-4">${metric('Checks','10','CHG-1948')}${metric('Pass','08','Sourced')}${metric('Warnings','02','Review')}${metric('Blockers','00','Approval allowed')}</div><div class="card" style="margin-top:14px"><div class="row-between"><strong>CHG-1948 · Kitchen wall +300 mm east</strong><span class="chip warn">NEEDS REVIEW</span></div>${[['ok','Geometry · PASS','No collision or closure issue','Geometry Engine'],['warn','Dimension · WARNING','980 mm vs 1000 mm minimum','MS-RST-CIRC-014'],['ok','Material · PASS','All finishes remain mapped','Material Library'],['ok','Structure · PASS','No locked geometry changed','Structural lock'],['warn','MEP · WARNING','2 outlets overlap moved wall','MEP graph'],['ok','Documentation · PASS','7 affected sheets identified','Dependency graph']].map(x=>`<div class="validation-item"><i class="status-dot ${x[0]}"></i><div><strong>${x[1]}</strong><small>${x[2]}</small></div><code>${x[3]}</code></div>`).join('')}<div style="text-align:right;margin-top:10px"><button class="btn">Edit proposal</button> <button class="btn primary" onclick="T('Approved → immutable Project Version V15 created.')">Approve commit</button></div></div>`}
function timeline(){return H('STUDIO OPERATIONS','Timeline','Milestones, daily priorities and delay risk tied to real design dependencies.')+`<div class="grid cols-3"><div class="card"><strong>This week</strong><div class="health-ring"></div><p class="mini-stat" style="text-align:center">Project health</p></div><div class="card"><strong>Critical path</strong><h3>Furniture details</h3><div class="progress"><i style="width:38%"></i></div><div class="risk-banner" style="margin-top:14px">Friday preview has 67% delay risk if ID-601–604 are not 80% complete by Thursday noon.</div></div><div class="card"><strong>Today’s priority</strong>${['Bar detail ID-601','Banquette ID-602','Resolve MEP warnings','Client preview board'].map((x,i)=>`<div class="validation-item"><i class="status-dot ${i<2?'warn':'ok'}"></i><div><strong>${x}</strong><small>${['3h','2.5h','45m','1.5h'][i]} estimated</small></div></div>`).join('')}</div></div>`}
function integrations(){let E=[['SU','SketchUp','Concept authoring, selection, materials','MOCK'],['RV','Revit','BIM, families, views, MEP','MOCK'],['AC','AutoCAD','DWG details and plotting','MOCK'],['VR','V-Ray','High-quality rendering','MOCK'],['IFC','IFC / BIM','Vendor-neutral exchange','READY'],['BL','Blender','Native AI 3D sandbox','READY'],['RH','Rhino.Compute','Parametric geometry','FUTURE']];return H('ENGINE LAYER','Integrations','ARCHON owns intent. Specialized engines plug in through isolated adapters.')+`<div class="grid cols-2">${E.map(x=>`<div class="engine-card"><div class="engine-logo">${x[0]}</div><div><h4>${x[1]}</h4><p>${x[2]}</p></div><span class="engine-state ${x[3]==='READY'?'ready':'mock'}">${x[3]}</span></div>`).join('')}</div><div class="card" style="margin-top:14px"><strong>Adapter contract</strong><div class="grid cols-4" style="margin-top:12px">${['Preview','Validate','Push ChangeSet','Reconcile'].map(x=>`<div class="tool" style="text-align:center">${x}</div>`).join('')}</div><div class="callout" style="margin-top:12px">Manual external edits return as proposals. They never silently overwrite approved ARCHON state.</div></div>`}
const P={home,genesis,dashboard,layout,canvas,studio3d,building,technical,materials,boq,validation,timeline,integrations};
function nav(p){S.page=p;location.hash=p;document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.nav===p));R();scrollTo(0,0)}
function R(){C.innerHTML=P[S.page]()} window.nav=nav;window.T=T;window.S=S;window.R=R;
document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));
$('#sendBtn').onclick=()=>{const v=$('#commandInput').value.trim();if(v){T(`Proposed ChangeSet created: “${v}”`);$('#commandInput').value=''}};
$('#commandInput').addEventListener('keydown',e=>{if(e.key==='Enter')$('#sendBtn').click()});
$('#voiceBtn').onclick=()=>T('Voice prototype: listening. Command will become a reviewed proposal.');
if(location.hash&&P[location.hash.slice(1)])S.page=location.hash.slice(1);R();
